INSERT INTO _dex_wave_h_profiles_0089 (
  target_table, slug, canonical_profile, feature
) VALUES ('mid_exchanges', 'spookyswap', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"dex:spookyswap","type":"dex","slug":"spookyswap","name":"SpookySwap","aliases":["Spooky","SpookySwap V2","SpookySwap V3"]},"classification":{"subtype":"Fantom-origin multichain spot AMM with V2 and V3 pools","tags":["spot_amm","concentrated_liquidity","multichain","fantom_origin","token_fee_share"],"chains":["Fantom Opera","Sonic","BitTorrent Chain","Horizen EON"],"jurisdictions":[]},"status":{"operating_state":"operating","as_of":"2026-08-03","claim_ids":["claim:spookyswap:status"]},"outcome":{"label":"operating_middling","as_of":"2026-08-03","rule_id":"exchange-lifecycle-v1","confidence":"high","claim_ids":["claim:spookyswap:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"SpookySwap is a non-custodial exchange that began as a Fantom-native constant-product AMM and later added concentrated-liquidity V3 pools. Traders swap from their wallets, LPs supply assets, and BOO holders can stake into xBOO for governance and a documented share of swap fees. The current interface also advertises farms, a launchpad and perpetuals, but this profile measures only SpookySwap-branded spot pools. It operates on Fantom and smaller deployments including Sonic, BitTorrent Chain and Horizen EON.","as_of":"2026-08-03","claim_ids":["claim:spookyswap:section:what_it_is:1","claim:spookyswap:section:what_it_is:2","claim:spookyswap:section:what_it_is:3"]},"what_happened":{"body":"SpookySwap launched in April 2021 to fill Fantom’s missing native exchange layer. It quickly paired BOO farming with limit orders, a built-in bridge and xBOO fee sharing, and its combined TVL later peaked near $1.66 billion on Jan. 17, 2022. Fantom activity and token incentives then contracted. A November 2023 frontend compromise forced a replacement interface; the operator said pool funds were safe. SpookySwap launched V3 concentrated liquidity in February 2024 and later appeared on Sonic, but current combined activity is only about $509,000 of TVL and $856,000 of 30-day spot volume.","as_of":"2026-08-03","claim_ids":["claim:spookyswap:section:what_happened:1","claim:spookyswap:section:what_happened:2","claim:spookyswap:section:what_happened:3"]},"why_this_outcome":{"body":"SpookySwap won early because it was one of Fantom’s first native exchanges and bundled the things local users needed: swaps, farms, a bridge and trader tools. That same distribution advantage concentrated the business in Fantom’s liquidity cycle. BOO emissions and xBOO rewards helped build liquidity, but they could not guarantee repeat trading after incentives and Fantom activity weakened. V3 and Sonic preserved the product rather than restoring its old scale. Public evidence supports chain concentration, incentive dependence and continuing competition as pressures, but it does not assign a precise share of the decline to any one cause.","as_of":"2026-08-03","claim_ids":["claim:spookyswap:section:why_this_outcome:1","claim:spookyswap:section:why_this_outcome:2","claim:spookyswap:section:why_this_outcome:3"]},"strategic_choices":{"body":"The team chose Fantom focus instead of broad multichain distribution at launch, then built a bridge, native limit orders and a recognizable interface to own that local user journey. It used BOO farms for liquidity and xBOO fee sharing for longer-term alignment. After activity fell, it kept V2 available, rebuilt the compromised frontend, shipped non-upgradeable V3 pools on several chains and followed Fantom’s successor ecosystem to Sonic. Those choices preserved continuity and optionality, but also split liquidity across versions, chains and fee tiers.","as_of":"2026-08-03","claim_ids":["claim:spookyswap:section:strategic_choices:1","claim:spookyswap:section:strategic_choices:2","claim:spookyswap:section:strategic_choices:3"]},"operating_model":{"body":"V2 pools use a constant-product AMM and historically charged 0.20% per swap, with 0.17% going to LPs and 0.03% used for the xBOO buyback path. V3 pools let LPs concentrate liquidity inside chosen price ranges and select fee tiers from 0.01% to 1.00%. The current adapter reports about $699 of 30-day fees and $23 of protocol or holder revenue. Those are tiny but real operating flows. TVL is inventory held in contracts, not a guarantee of tradeable depth, and neither fees nor revenue equals profit.","as_of":"2026-08-03","claim_ids":["claim:spookyswap:section:operating_model:1","claim:spookyswap:section:operating_model:2","claim:spookyswap:section:operating_model:3"]},"token_and_value_capture":{"body":"BOO is the venue’s governance and incentive token. Farms distributed BOO to LPs, while staking BOO into xBOO historically gave holders governance participation and exposure to the 0.03% V2 buyback allocation. That is a real link to exchange usage, but current fee generation is small and the reviewed sources do not prove how much xBOO currently distributes after incentives, contract changes and multiple versions. BOO is not equity, and Sonic’s chain token or unrelated Sonic DEX tokens do not accrue to BOO holders.","as_of":"2026-08-03","claim_ids":["claim:spookyswap:section:token_and_value_capture:1","claim:spookyswap:section:token_and_value_capture:2","claim:spookyswap:section:token_and_value_capture:3"]},"counterfactual":{"body":"Earlier expansion beyond Fantom could have reduced dependence on one chain, but it might also have diluted the local advantage that made SpookySwap successful. Tying BOO emissions to fee-supported demand could have made organic retention easier to see. A single forced migration from V2 to V3 might concentrate liquidity, but would strand users and remove a familiar fallback. The realistic alternative was staged expansion with hard usage thresholds, explicit version sunsets and fee-backed incentives; public evidence cannot prove that plan would have restored peak scale.","as_of":"2026-08-03","claim_ids":["claim:spookyswap:section:counterfactual:1","claim:spookyswap:section:counterfactual:2","claim:spookyswap:section:counterfactual:3"]},"risks_and_unknowns":{"body":"The main risks are fragmented liquidity, low fee generation, BOO incentive dependence, frontend compromise and uncertain control across old and new contracts. The 2023 incident shows that audited pool contracts do not protect users from a compromised website. The 2021 audits were version-specific and do not cover every later deployment or frontend. Current unknowns include active traders by chain, direct versus aggregator flow, xBOO net distributions, contract-control boundaries and whether low-volume deployments can support maintenance.","as_of":"2026-08-03","claim_ids":["claim:spookyswap:section:risks_and_unknowns:1","claim:spookyswap:section:risks_and_unknowns:2","claim:spookyswap:section:risks_and_unknowns:3"]},"lifecycle":{"body":"SpookySwap launched on Fantom in April 2021, grew with the chain and BOO incentives, and reached a combined TVL peak near $1.66 billion in January 2022. As Fantom’s DeFi cycle faded, balances, trading and fees declined. The team rebuilt the frontend after a November 2023 compromise, launched V3 on Fantom, Horizen EON and BitTorrent Chain in February 2024, and later carried the brand to Sonic. It remains a working exchange with legacy and newer deployments, but its current scale is a small fraction of the peak.","as_of":"2026-08-03","claim_ids":["claim:spookyswap:section:lifecycle:1","claim:spookyswap:section:lifecycle:2","claim:spookyswap:section:lifecycle:3"]},"outlook_and_watch":{"body":"SpookySwap’s outlook is continued operation at modest scale unless Sonic or another deployment creates sustained demand. Watch 30- and 90-day spot volume by chain, fee-backed BOO distributions, active traders, liquidity concentration and frontend-security notices. Growth should count only when trades, fees and recurring users rise together without relying mainly on BOO emissions. A rising Sonic chain does not change this call unless SpookySwap captures that activity, and perpetuals or launchpad usage must remain separate from spot results.","as_of":"2026-08-03","claim_ids":["claim:spookyswap:section:outlook_and_watch:1","claim:spookyswap:section:outlook_and_watch:2","claim:spookyswap:section:outlook_and_watch:3"]}}},"metrics":[{"id":"metric:spookyswap:spot-volume-24h:2026-08-03","dimension":"spot_volume","label":"Combined spot volume, 24h","value":9609,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported latest point"},"as_of":"2026-08-03","method":"DefiLlama combined total24h.","scope":{"product":"SpookySwap-branded spot pools across supported chains","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:spookyswap:metric:spot-volume-24h"],"quality_flags":[]},{"id":"metric:spookyswap:spot-volume-30d:2026-08-03","dimension":"spot_volume","label":"Combined spot volume, 30d","value":856059,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"rolling 30 days"},"as_of":"2026-08-03","method":"DefiLlama combined total30d.","scope":{"product":"SpookySwap-branded spot pools across supported chains","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:spookyswap:metric:spot-volume-30d"],"quality_flags":[]},{"id":"metric:spookyswap:tvl-latest:2026-08-03","dimension":"tvl","label":"Combined TVL","value":509309,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported latest point"},"as_of":"2026-08-03","method":"Sum of currentChainTvls without double-counted borrowed or staking buckets.","scope":{"product":"Fantom, Sonic, BitTorrent Chain and Horizen EON pools","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:spookyswap:metric:tvl-latest"],"quality_flags":["tvl_not_market_depth"]},{"id":"metric:spookyswap:tvl-peak:2022-01-17","dimension":"tvl","label":"Historical peak TVL","value":1664547468,"unit":"usd","currency":"USD","window":{"start":null,"end":"2022-01-17","definition":"historical maximum"},"as_of":"2022-01-17","method":"Maximum combined historical totalLiquidityUSD, dated 2022-01-17.","scope":{"product":"exchange venue","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:spookyswap:metric:tvl-peak"],"quality_flags":["historical_not_current"]},{"id":"metric:spookyswap:fees-30d:2026-08-03","dimension":"fees","label":"Trading fees, 30d","value":699.32,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"rolling 30 days"},"as_of":"2026-08-03","method":"DefiLlama total30d fee adapter.","scope":{"product":"exchange venue","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:spookyswap:metric:fees-30d"],"quality_flags":["fees_not_profit"]},{"id":"metric:spookyswap:revenue-30d:2026-08-03","dimension":"protocol_revenue","label":"Protocol and holder revenue, 30d","value":22.97,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"rolling 30 days"},"as_of":"2026-08-03","method":"DefiLlama dailyRevenue total30d.","scope":{"product":"exchange venue","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:spookyswap:metric:revenue-30d"],"quality_flags":["adapter_defined_revenue"]}],"events":[{"id":"event:spookyswap:launch","type":"launch","date":"2021-04-14","description":"SpookySwap publicly introduced its Fantom-native AMM.","claim_ids":["claim:spookyswap:event:launch"]},{"id":"event:spookyswap:v3-launch","type":"product_change","date":"2024-02-28","description":"SpookySwap launched V3 concentrated-liquidity pools on Fantom, Horizen EON and BitTorrent Chain.","claim_ids":["claim:spookyswap:event:v3-launch"]}],"sources":[{"id":"source:spookyswap:app","title":"SpookySwap application","url":"https://spooky.fi/","publisher":"SpookySwap","published_at":null,"accessed_at":"2026-08-03T20:05:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T20:05:00Z","content_hash":null,"evidence_locator":"Current product surface for swaps, V3 liquidity, BOO staking, farms, launchpad and Sonic-facing operation.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:spookyswap:introduction","title":"Introducing SpookySwap","url":"https://spookyswap.medium.com/introducing-spookyswap-less-gas-more-trades-faster-transactions-extra-spooky-da8d6ed8514a","publisher":"SpookySwap","published_at":"2021-04-14","accessed_at":"2026-08-03T20:05:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T20:05:00Z","content_hash":null,"evidence_locator":"Dated operator launch rationale, Fantom focus and governance intent.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:spookyswap:development","title":"SpookySwap Development Update #3","url":"https://spookyswap.medium.com/spookyswap-development-update-3-2555213db3a4","publisher":"SpookySwap","published_at":"2021-06-23","accessed_at":"2026-08-03T20:05:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T20:05:00Z","content_hash":null,"evidence_locator":"Early Fantom traction, xBOO fee split, product priorities and audit claim.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:spookyswap:v3-launch","title":"SpookySwap V3 Launch Announcement","url":"https://spookyswap.medium.com/spookyswap-v3-launch-announcement-c1a3c86f9100","publisher":"SpookySwap","published_at":"2024-02-26","accessed_at":"2026-08-03T20:05:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T20:05:00Z","content_hash":null,"evidence_locator":"Dated V3 concentrated-liquidity launch, chains, fee tiers and BOO governance description.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:spookyswap:frontend-incident","title":"Spooky Frontend Exploit Update","url":"https://spookyswap.medium.com/spooky-frontend-exploit-update-funds-are-safe-ba5f7e8fa300","publisher":"SpookySwap","published_at":"2023-11-19","accessed_at":"2026-08-03T20:05:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T20:05:00Z","content_hash":null,"evidence_locator":"Operator account of the frontend compromise, response and statement that pool contracts and funds were not drained.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:spookyswap:docs","title":"SpookySwap V3 documentation","url":"https://docs.spooky.fi/","publisher":"SpookySwap","published_at":null,"accessed_at":"2026-08-03T20:05:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T20:05:00Z","content_hash":null,"evidence_locator":"Current V3 scope, non-upgradeable contract framing, supported networks and BOO role.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:spookyswap:sonic-routing","title":"1inch Integrates Sonic","url":"https://blog.soniclabs.com/1inch-integrates-sonic-swaps-speed-and-seamless-defi/","publisher":"Sonic Labs","published_at":"2025-02-14","accessed_at":"2026-08-03T20:05:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T20:05:00Z","content_hash":null,"evidence_locator":"Sonic ecosystem routing context that includes SpookySwap among available liquidity sources.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:spookyswap:audit","title":"SpookySwap security profile","url":"https://skynet.certik.com/projects/spookyswap","publisher":"CertiK","published_at":null,"accessed_at":"2026-08-03T20:05:00Z","archive_url":null,"tier":"A","role":"independent","access_state":"reachable","checked_at":"2026-08-03T20:05:00Z","content_hash":null,"evidence_locator":"Version-scoped 2021 audit history and current coverage limitations.","direct_http_status":403,"access_method":"browser_rendered_page"},{"id":"source:spookyswap:tvl","title":"SpookySwap protocol TVL API","url":"https://api.llama.fi/protocol/spookyswap","publisher":"DefiLlama","published_at":null,"accessed_at":"2026-08-03T20:05:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T20:05:00Z","content_hash":null,"evidence_locator":"Combined Fantom, Sonic, BitTorrent and Horizen balances plus historical TVL series.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:spookyswap:volume","title":"SpookySwap DEX volume API","url":"https://api.llama.fi/summary/dexs/spookyswap?dataType=dailyVolume","publisher":"DefiLlama","published_at":null,"accessed_at":"2026-08-03T20:05:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T20:05:00Z","content_hash":null,"evidence_locator":"Combined spot-volume series across supported SpookySwap deployments.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:spookyswap:fees","title":"SpookySwap fees API","url":"https://api.llama.fi/summary/fees/spookyswap?dataType=dailyFees","publisher":"DefiLlama","published_at":null,"accessed_at":"2026-08-03T20:05:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T20:05:00Z","content_hash":null,"evidence_locator":"Combined swap-fee observations; fees are not profit.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:spookyswap:revenue","title":"SpookySwap revenue API","url":"https://api.llama.fi/summary/fees/spookyswap?dataType=dailyRevenue","publisher":"DefiLlama","published_at":null,"accessed_at":"2026-08-03T20:05:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T20:05:00Z","content_hash":null,"evidence_locator":"Adapter-defined protocol and holder revenue observations.","direct_http_status":200,"access_method":"direct_http"}],"claims":[{"id":"claim:spookyswap:status","field_path":"status.operating_state","assertion":"SpookySwap was operating at the review date.","value":"operating","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spookyswap:app","source:spookyswap:tvl","source:spookyswap:volume"],"evidence_locator":"Current interface plus nonzero multichain balances and trades establish continued operation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:outcome","field_path":"outcome.label","assertion":"SpookySwap is classified operating middling as of 2026-08-03.","value":"operating_middling","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:spookyswap:introduction","source:spookyswap:v3-launch","source:spookyswap:tvl","source:spookyswap:volume","source:spookyswap:fees"],"evidence_locator":"Durable product continuity but activity far below the historical peak supports a middling outcome.","support_direction":"supports","note":"Analyst lifecycle classification; observed activity and events do not prove one exclusive cause.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body","assertion":"SpookySwap operates non-custodial V2 and V3 spot pools.","value":"SpookySwap operates non-custodial V2 and V3 spot pools.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spookyswap:app","source:spookyswap:docs","source:spookyswap:v3-launch"],"evidence_locator":"Current product and dated V3 descriptions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body","assertion":"BOO and xBOO connect governance and a documented portion of swap fees.","value":"BOO and xBOO connect governance and a documented portion of swap fees.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spookyswap:app","source:spookyswap:development"],"evidence_locator":"Current staking surface and original fee-split announcement.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:what_it_is:3","field_path":"analysis.sections.what_it_is.body","assertion":"Spot metrics exclude the launchpad, bridge and perpetuals products.","value":"Spot metrics exclude the launchpad, bridge and perpetuals products.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:spookyswap:app","source:spookyswap:volume"],"evidence_locator":"Product inventory and adapter scope.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:what_happened:1","field_path":"analysis.sections.what_happened.body","assertion":"SpookySwap launched as a Fantom-focused DEX in April 2021.","value":"SpookySwap launched as a Fantom-focused DEX in April 2021.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spookyswap:introduction"],"evidence_locator":"Dated operator introduction.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:what_happened:2","field_path":"analysis.sections.what_happened.body","assertion":"Combined SpookySwap TVL peaked near $1.66 billion on 2022-01-17.","value":"Combined SpookySwap TVL peaked near $1.66 billion on 2022-01-17.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spookyswap:tvl"],"evidence_locator":"Historical provider series.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:what_happened:3","field_path":"analysis.sections.what_happened.body","assertion":"The venue restored its frontend, launched V3 and continued across additional chains.","value":"The venue restored its frontend, launched V3 and continued across additional chains.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spookyswap:frontend-incident","source:spookyswap:v3-launch","source:spookyswap:app"],"evidence_locator":"Dated incident, V3 launch and current interface.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body","assertion":"Early Fantom-native distribution helped SpookySwap acquire liquidity and users.","value":"Early Fantom-native distribution helped SpookySwap acquire liquidity and users.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:spookyswap:introduction","source:spookyswap:development"],"evidence_locator":"Launch rationale and early traction.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body","assertion":"BOO rewards and xBOO fee sharing tied liquidity to token and fee economics.","value":"BOO rewards and xBOO fee sharing tied liquidity to token and fee economics.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spookyswap:development","source:spookyswap:app"],"evidence_locator":"Documented incentive and fee model.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:why_this_outcome:3","field_path":"analysis.sections.why_this_outcome.body","assertion":"The evidence does not quantify how much chain conditions, emissions, competition or product execution caused the decline.","value":"The evidence does not quantify how much chain conditions, emissions, competition or product execution caused the decline.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:spookyswap:tvl","source:spookyswap:volume","source:spookyswap:v3-launch"],"evidence_locator":"Outcome series without causal decomposition.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body","assertion":"SpookySwap deliberately launched as a Fantom-focused exchange and distribution hub.","value":"SpookySwap deliberately launched as a Fantom-focused exchange and distribution hub.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spookyswap:introduction","source:spookyswap:development"],"evidence_locator":"Operator launch and development record.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body","assertion":"The team chose BOO farming and xBOO fee sharing to attract and retain liquidity.","value":"The team chose BOO farming and xBOO fee sharing to attract and retain liquidity.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spookyswap:development","source:spookyswap:app"],"evidence_locator":"Documented token model.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:strategic_choices:3","field_path":"analysis.sections.strategic_choices.body","assertion":"The team retained V2 while adding multichain V3 and Sonic support.","value":"The team retained V2 while adding multichain V3 and Sonic support.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spookyswap:v3-launch","source:spookyswap:docs","source:spookyswap:app"],"evidence_locator":"Version and chain inventory.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:operating_model:1","field_path":"analysis.sections.operating_model.body","assertion":"The documented V2 split sent 0.17% to LPs and 0.03% to the xBOO buyback path.","value":"The documented V2 split sent 0.17% to LPs and 0.03% to the xBOO buyback path.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spookyswap:development"],"evidence_locator":"Operator fee-model announcement.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:operating_model:2","field_path":"analysis.sections.operating_model.body","assertion":"V3 pools use concentrated liquidity with several fee tiers.","value":"V3 pools use concentrated liquidity with several fee tiers.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spookyswap:v3-launch","source:spookyswap:docs"],"evidence_locator":"Operator V3 design record.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:operating_model:3","field_path":"analysis.sections.operating_model.body","assertion":"The adapter recorded about $699 of 30-day fees and $23 of 30-day revenue at review time.","value":"The adapter recorded about $699 of 30-day fees and $23 of 30-day revenue at review time.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spookyswap:fees","source:spookyswap:revenue"],"evidence_locator":"Current provider observations.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body","assertion":"BOO funded farms and governance in the original operating model.","value":"BOO funded farms and governance in the original operating model.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spookyswap:development","source:spookyswap:v3-launch"],"evidence_locator":"Operator token and governance descriptions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:token_and_value_capture:2","field_path":"analysis.sections.token_and_value_capture.body","assertion":"xBOO historically received value through the documented V2 buyback fee allocation.","value":"xBOO historically received value through the documented V2 buyback fee allocation.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spookyswap:development"],"evidence_locator":"Dated fee-split announcement.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:token_and_value_capture:3","field_path":"analysis.sections.token_and_value_capture.body","assertion":"Current net distributions to xBOO holders are not established by the reviewed sources.","value":"Current net distributions to xBOO holders are not established by the reviewed sources.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:spookyswap:app","source:spookyswap:revenue"],"evidence_locator":"Current interface and adapter do not provide a complete holder ledger.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:counterfactual:1","field_path":"analysis.sections.counterfactual.body","assertion":"Earlier multichain expansion could reduce single-chain concentration while weakening local focus.","value":"Earlier multichain expansion could reduce single-chain concentration while weakening local focus.","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:spookyswap:introduction","source:spookyswap:v3-launch"],"evidence_locator":"Observed launch and later expansion support the trade-off.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:counterfactual:2","field_path":"analysis.sections.counterfactual.body","assertion":"Fee-triggered emissions could make retained demand easier to distinguish from subsidized liquidity.","value":"Fee-triggered emissions could make retained demand easier to distinguish from subsidized liquidity.","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:spookyswap:development","source:spookyswap:fees"],"evidence_locator":"Incentive design and current fee observations.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:counterfactual:3","field_path":"analysis.sections.counterfactual.body","assertion":"No reviewed source proves a different migration or emission plan would restore historical scale.","value":"No reviewed source proves a different migration or emission plan would restore historical scale.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:spookyswap:tvl","source:spookyswap:volume"],"evidence_locator":"Counterfactual is not observed.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:risks_and_unknowns:1","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"A frontend compromise can endanger users even when pool contracts are not drained.","value":"A frontend compromise can endanger users even when pool contracts are not drained.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:spookyswap:frontend-incident"],"evidence_locator":"Operator incident account.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:risks_and_unknowns:2","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"The reviewed audit history does not cover every current contract and interface.","value":"The reviewed audit history does not cover every current contract and interface.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spookyswap:audit","source:spookyswap:v3-launch"],"evidence_locator":"Audit dates and later deployment scope.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:risks_and_unknowns:3","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"Trader retention, routed-flow share and current control boundaries remain unknown.","value":"Trader retention, routed-flow share and current control boundaries remain unknown.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:spookyswap:app","source:spookyswap:volume","source:spookyswap:sonic-routing"],"evidence_locator":"No complete current disclosure.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:lifecycle:1","field_path":"analysis.sections.lifecycle.body","assertion":"SpookySwap moved from Fantom-native launch to a multichain V2 and V3 product.","value":"SpookySwap moved from Fantom-native launch to a multichain V2 and V3 product.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spookyswap:introduction","source:spookyswap:v3-launch","source:spookyswap:app"],"evidence_locator":"Dated launch, V3 release and current surface.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:lifecycle:2","field_path":"analysis.sections.lifecycle.body","assertion":"The November 2023 frontend incident did not end the venue.","value":"The November 2023 frontend incident did not end the venue.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spookyswap:frontend-incident","source:spookyswap:app"],"evidence_locator":"Incident response and current operation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:lifecycle:3","field_path":"analysis.sections.lifecycle.body","assertion":"Current TVL and volume remain far below their historical levels.","value":"Current TVL and volume remain far below their historical levels.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spookyswap:tvl","source:spookyswap:volume"],"evidence_locator":"Current and historical provider series.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Sustained chain-level spot volume and fees are the clearest recovery signals.","value":"Sustained chain-level spot volume and fees are the clearest recovery signals.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:spookyswap:volume","source:spookyswap:fees","source:spookyswap:tvl"],"evidence_locator":"Current comparable series.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:section:outlook_and_watch:2","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Sonic growth only supports recovery if SpookySwap captures measurable usage.","value":"Sonic growth only supports recovery if SpookySwap captures measurable usage.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:spookyswap:sonic-routing","source:spookyswap:volume"],"evidence_locator":"Chain and venue scopes are