 be combined across unlike scopes.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:metric:revenue-30d","field_path":"metrics[metric:spookyswap:revenue-30d:2026-08-03].value","assertion":"Protocol and holder revenue, 30d was 22.97 USD for the stated scope and window.","value":22.97,"as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spookyswap:revenue"],"evidence_locator":"Provider response replayed between 2026-08-03T19:59:00Z and 2026-08-03T20:05:00Z; exact value retained in the research artifact.","support_direction":"supports","note":"Point-in-time provider observation; adapters may revise same-day values and must not be combined across unlike scopes.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:event:launch","field_path":"events[event:spookyswap:launch]","assertion":"SpookySwap publicly introduced its Fantom-native AMM.","value":"2021-04-14","as_of":"2021-04-14","confidence":"high","kind":"fact","source_ids":["source:spookyswap:introduction"],"evidence_locator":"Dated operator launch announcement.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spookyswap:event:v3-launch","field_path":"events[event:spookyswap:v3-launch]","assertion":"SpookySwap launched V3 concentrated-liquidity pools on Fantom, Horizen EON and BitTorrent Chain.","value":"2024-02-28","as_of":"2024-02-28","confidence":"high","kind":"fact","source_ids":["source:spookyswap:v3-launch"],"evidence_locator":"Dated operator launch announcement.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}}],"freshness":{"state":"current","last_reviewed_at":"2026-08-03T20:05:00Z","next_review_at":"2026-08-10T20:05:00Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"high","unsourced_fields":["Active traders by chain","Fee-funded BOO yield share","Direct versus routed Sonic flow","Current operational control map"]},"extensions":{"legacy_origin":"mid_exchanges","observation_window":{"started_at":"2026-08-03T19:59:00Z","completed_at":"2026-08-03T20:05:00Z"},"explicit_unknowns":["How many recurring traders use SpookySwap on each supported chain?","What share of current BOO staking distributions comes from fees rather than incentives?","How much Sonic volume is routed by aggregators versus acquired directly?","Which current contracts, frontends and governance actions are controlled by identifiable maintainers?"],"identity_boundary":"This profile covers SpookySwap-branded spot V2 and V3 pools across Fantom, Sonic, BitTorrent Chain and Horizen EON. The launchpad, bridge integrations and linked perpetuals interface are separate products; their activity is not added to spot volume. Fantom or Sonic chain growth is not automatically SpookySwap growth.","methodology_notes":["Every material field is attached to atomic pending claims; a person must review those claims before the report can be published.","Routed volume is not additive to underlying DEX volume, TVL is not market depth, fees are not profit, residual balances are not an operating venue, and observed co-movement is not causation.","Documented decisions, observed outcomes, analyst inferences and unresolved unknowns are kept separate.","Combined adapter metrics are used only where the provider explicitly aggregates SpookySwap deployments; V2-only numbers are not added again.","The November 2023 event is treated as a frontend compromise based on the operator account, not a smart-contract pool loss."]}}', '{"kind":"dex","slug":"spookyswap","lifecycle":"mid","operating_model":"Operating multichain V2 and V3 spot AMM with BOO/xBOO governance and fee linkage.","product_cohort":"multichain_spot_amm","custody_model":"non_custodial","primary_chain":"Fantom Opera","chains":["Fantom Opera","Sonic","BitTorrent Chain","Horizen EON"],"token_status":"launched","token_symbol":"BOO","token_launch_date":null,"token_launch_timing":"at_or_near_launch","token_strategy":"liquidity_emissions_governance_and_xboo_fee_buyback","token_source_url":"https://spooky.fi/","metric_type":"spot_volume","metric_unit":"usd","metric_window":"rolling_30_days","metric_as_of":"2026-08-03","metric_observed_at":"2026-08-03T19:59:00Z","comparability_key":"dex|multichain_spot_amm|spot_volume|usd|rolling_30_days","evidence":{"canonical_profile":true,"claims_pending_human_review":true,"identity_boundary":"This profile covers SpookySwap-branded spot V2 and V3 pools across Fantom, Sonic, BitTorrent Chain and Horizen EON. The launchpad, bridge integrations and linked perpetuals interface are separate products; their activity is not added to spot volume. Fantom or Sonic chain growth is not automatically SpookySwap growth.","metric_replayed_at":"2026-08-03T19:59:00Z","source_count":12},"quality_label":"verified","quality_issues":[],"lifecycle_evidence_date":"2026-08-03","last_verified_at":"2026-08-03","next_review_at":"2026-08-10","freshness_status":"current","updated_at":"2026-08-03"}');

INSERT INTO _dex_wave_h_profiles_0089 (
  target_table, slug, canonical_profile, feature
) VALUES ('mid_exchanges', 'spiritswap', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"dex:spiritswap","type":"dex","slug":"spiritswap","name":"SpiritSwap","aliases":["Spirit Swap"]},"classification":{"subtype":"Fantom-native constant-product and stable-swap DEX after rescue handoff","tags":["spot_amm","stableswap","fantom_native","vote_escrow","rescued","declining"],"chains":["Fantom Opera"],"jurisdictions":[]},"status":{"operating_state":"operating","as_of":"2026-08-03","claim_ids":["claim:spiritswap:status"]},"outcome":{"label":"rescued_declining","as_of":"2026-08-03","rule_id":"exchange-lifecycle-v1","confidence":"high","claim_ids":["claim:spiritswap:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"SpiritSwap is a non-custodial Fantom exchange built around constant-product and stable-swap pools. Traders swap from their wallets, LPs deposit paired assets, and farms historically paid SPIRIT rewards. Locking SPIRIT created inSPIRIT for boosted farms, governance and a documented share of exchange revenue. SpiritSwap also presented a bridge interface, but the underlying Multichain infrastructure was a separate protocol. The current site and adapters show that the venue still exists, though at very small scale.","as_of":"2026-08-03","claim_ids":["claim:spiritswap:section:what_it_is:1","claim:spiritswap:section:what_it_is:2","claim:spiritswap:section:what_it_is:3"]},"what_happened":{"body":"SpiritSwap launched on Fantom in April 2021, grew through SPIRIT farms and inSPIRIT locks, and reached about $373.03 million of TVL on Jan. 17, 2022. In 2023, Multichain’s failure trapped or drained the treasury assets SpiritSwap needed for salaries, development and marketing. The team announced a Sept. 1 shutdown, then users approved a transfer to the Power team with a reported $200,000 USDC treasury commitment. The rescue kept the venue alive. Current adapters show roughly $229,706 of TVL and only $31,309 of 30-day volume, so survival did not restore former scale.","as_of":"2026-08-03","claim_ids":["claim:spiritswap:section:what_happened:1","claim:spiritswap:section:what_happened:2","claim:spiritswap:section:what_happened:3"]},"why_this_outcome":{"body":"SpiritSwap’s Fantom focus built a clear local product and community, but also concentrated demand, treasury assets and bridge exposure in one ecosystem. SPIRIT emissions and inSPIRIT voting helped attract liquidity while fees were strong. They could not protect operating runway when Multichain failed and Fantom liquidity shrank. The rescue worked because the code, brand and community could be transferred to another team. The evidence strongly supports treasury concentration and the Multichain shock as the immediate closure trigger; it does not quantify how much chain decline, competition, emissions or later execution explains today’s low scale.","as_of":"2026-08-03","claim_ids":["claim:spiritswap:section:why_this_outcome:1","claim:spiritswap:section:why_this_outcome:2","claim:spiritswap:section:why_this_outcome:3"]},"strategic_choices":{"body":"SpiritSwap chose deep Fantom specialization, a branded bridge interface, SPIRIT liquidity emissions and vote-locked inSPIRIT. That package made the venue useful inside Fantom, but placed treasury and distribution risk around the same ecosystem and bridge stack. After Multichain broke the operating budget, the community chose a team transfer and recapitalization rather than shut the contracts and interface. That preserved continuity but left users dependent on a new stewardship group whose current control and financial disclosures are incomplete.","as_of":"2026-08-03","claim_ids":["claim:spiritswap:section:strategic_choices:1","claim:spiritswap:section:strategic_choices:2","claim:spiritswap:section:strategic_choices:3"]},"operating_model":{"body":"SpiritSwap earned swap fees from AMM trades and historically allocated value among LPs, the protocol and inSPIRIT holders. LPs also received SPIRIT emissions, while inSPIRIT locks boosted farms and directed governance. At review time, the data adapter recorded about $95 of 30-day fees, $13.85 of protocol revenue and zero holder revenue. That does not prove every inSPIRIT contract has stopped paying, but it shows the current tracked business is tiny. The roughly $229,706 of TVL is contract inventory, not proof of deep execution or a funded operating team.","as_of":"2026-08-03","claim_ids":["claim:spiritswap:section:operating_model:1","claim:spiritswap:section:operating_model:2","claim:spiritswap:section:operating_model:3"]},"token_and_value_capture":{"body":"SPIRIT launched with the product’s farming economy, and locking it created inSPIRIT. The advertised rights included boosted farm emissions, governance over incentives and community proposals, and a share of swap revenue. That linked the token to exchange use when volume and fees were meaningful. Current fee and holder-revenue observations are very small, and the site does not publish a complete post-rescue distribution ledger. SPIRIT is not ownership of Fantom, Multichain or Power, and success elsewhere in those ecosystems does not accrue automatically to holders.","as_of":"2026-08-03","claim_ids":["claim:spiritswap:section:token_and_value_capture:1","claim:spiritswap:section:token_and_value_capture:2","claim:spiritswap:section:token_and_value_capture:3"]},"counterfactual":{"body":"A treasury split across native stable assets, qualified custodial arrangements and bridge-risk caps could have prevented one infrastructure failure from ending the operating budget. Multichain exposure could also have been separated from payroll and runway. Earlier expansion beyond Fantom might diversify demand, but would add deployment cost and dilute local focus. After the loss, closure would have been cleaner than an opaque rescue, while the transfer preserved upside. The strongest counterfactual is a documented treasury policy plus public handoff controls, not simply a different AMM curve.","as_of":"2026-08-03","claim_ids":["claim:spiritswap:section:counterfactual:1","claim:spiritswap:section:counterfactual:2","claim:spiritswap:section:counterfactual:3"]},"risks_and_unknowns":{"body":"The main risks are unclear post-rescue control, thin liquidity, low fees, dormant token rights, bridge liabilities and old contract or frontend permissions. A 2021 core audit covered specific contracts; it did not cover Multichain treasury exposure, the 2023 handoff or every current interface. The public site’s zero and NaN headline figures also weaken operational transparency. Users still need verified contracts, successful trade simulation and withdrawal paths rather than assuming a branded page is enough.","as_of":"2026-08-03","claim_ids":["claim:spiritswap:section:risks_and_unknowns:1","claim:spiritswap:section:risks_and_unknowns:2","claim:spiritswap:section:risks_and_unknowns:3"]},"lifecycle":{"body":"SpiritSwap launched in April 2021, grew into a major Fantom venue and peaked in early 2022. The Fantom cycle then weakened. Multichain’s 2023 failure impaired SpiritSwap’s treasury so severely that the team announced a shutdown. A community vote transferred the project to Power days later and prevented immediate closure. The current interface remains online and adapters still record trades, fees and balances, but all are far below the peak. SpiritSwap is best described as rescued and operating at declining, marginal scale—not dead and not recovered.","as_of":"2026-08-03","claim_ids":["claim:spiritswap:section:lifecycle:1","claim:spiritswap:section:lifecycle:2","claim:spiritswap:section:lifecycle:3"]},"outlook_and_watch":{"body":"SpiritSwap can remain online without becoming a healthy business. Watch 30- and 90-day volume, fee and TVL trends; verified control of treasury and contracts; successful swaps and withdrawals; inSPIRIT distributions; and dated releases from the rescue team. Recovery requires recurring users, deeper liquidity and fee-funded operations without another treasury subsidy. Fantom or Sonic ecosystem growth should not change the call unless SpiritSwap itself captures measurable activity.","as_of":"2026-08-03","claim_ids":["claim:spiritswap:section:outlook_and_watch:1","claim:spiritswap:section:outlook_and_watch:2","claim:spiritswap:section:outlook_and_watch:3"]}}},"metrics":[{"id":"metric:spiritswap:spot-volume-24h:2026-08-03","dimension":"spot_volume","label":"Spot volume, 24h","value":511,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported latest point"},"as_of":"2026-08-03","method":"DefiLlama total24h.","scope":{"product":"SpiritSwap Fantom spot pools","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:spiritswap:metric:spot-volume-24h"],"quality_flags":[]},{"id":"metric:spiritswap:spot-volume-30d:2026-08-03","dimension":"spot_volume","label":"Spot volume, 30d","value":31309,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"rolling 30 days"},"as_of":"2026-08-03","method":"DefiLlama total30d.","scope":{"product":"SpiritSwap Fantom spot pools","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:spiritswap:metric:spot-volume-30d"],"quality_flags":[]},{"id":"metric:spiritswap:tvl-latest:2026-08-03","dimension":"tvl","label":"Current TVL","value":229706,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported latest point"},"as_of":"2026-08-03","method":"Current Fantom TVL without double-counted staking or borrowed buckets.","scope":{"product":"exchange venue","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:spiritswap:metric:tvl-latest"],"quality_flags":["tvl_not_market_depth"]},{"id":"metric:spiritswap:tvl-peak:2022-01-17","dimension":"tvl","label":"Historical peak TVL","value":373029262,"unit":"usd","currency":"USD","window":{"start":null,"end":"2022-01-17","definition":"historical maximum"},"as_of":"2022-01-17","method":"Maximum historical totalLiquidityUSD, dated 2022-01-17.","scope":{"product":"exchange venue","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:spiritswap:metric:tvl-peak"],"quality_flags":["historical_not_current"]},{"id":"metric:spiritswap:fees-30d:2026-08-03","dimension":"fees","label":"Trading fees, 30d","value":95,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"rolling 30 days"},"as_of":"2026-08-03","method":"DefiLlama total30d fee adapter.","scope":{"product":"exchange venue","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:spiritswap:metric:fees-30d"],"quality_flags":["fees_not_profit"]},{"id":"metric:spiritswap:revenue-30d:2026-08-03","dimension":"protocol_revenue","label":"Protocol revenue, 30d","value":13.85,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"rolling 30 days"},"as_of":"2026-08-03","method":"DefiLlama dailyRevenue total30d.","scope":{"product":"exchange venue","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:spiritswap:metric:revenue-30d"],"quality_flags":["adapter_defined_revenue"]}],"events":[{"id":"event:spiritswap:shutdown-announced","type":"closure_plan","date":"2023-08-09","description":"SpiritSwap announced a September shutdown after Multichain-linked treasury losses removed its operating budget.","claim_ids":["claim:spiritswap:event:shutdown-announced"]},{"id":"event:spiritswap:rescue-approved","type":"rescue","date":"2023-08-16","description":"Users approved transfer to Power with a reported $200,000 USDC treasury commitment.","claim_ids":["claim:spiritswap:event:rescue-approved"]}],"sources":[{"id":"source:spiritswap:app","title":"SpiritSwap application","url":"https://www.spiritswap.finance/","publisher":"SpiritSwap","published_at":null,"accessed_at":"2026-08-03T20:05:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T20:05:00Z","content_hash":null,"evidence_locator":"Current Fan