s","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spiritswap:outcome","field_path":"outcome.label","assertion":"SpiritSwap is classified rescued declining as of 2026-08-03.","value":"rescued_declining","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:spiritswap:shutdown","source:spiritswap:rescue","source:spiritswap:tvl","source:spiritswap:volume","source:spiritswap:revenue"],"evidence_locator":"Averted closure plus durable but very small activity supports rescued and declining status.","support_direction":"supports","note":"Analyst lifecycle classification; observed activity and events do not prove one exclusive cause.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spiritswap:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body","assertion":"SpiritSwap operates Fantom AMM and stable-swap products.","value":"SpiritSwap operates Fantom AMM and stable-swap products.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spiritswap:app","source:spiritswap:audit"],"evidence_locator":"Current product and original core design.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spiritswap:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body","assertion":"SPIRIT and inSPIRIT historically linked farming, governance and fee participation.","value":"SPIRIT and inSPIRIT historically linked farming, governance and fee participation.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spiritswap:app","source:spiritswap:inspirit","source:spiritswap:treasury-context"],"evidence_locator":"Current branded surface and historical independent description.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spiritswap:section:what_it_is:3","field_path":"analysis.sections.what_it_is.body","assertion":"Multichain bridge infrastructure was an external dependency, not the SpiritSwap exchange.","value":"Multichain bridge infrastructure was an external dependency, not the SpiritSwap exchange.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:spiritswap:shutdown","source:spiritswap:treasury-context"],"evidence_locator":"Independent incident accounts.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spiritswap:section:what_happened:1","field_path":"analysis.sections.what_happened.body","assertion":"SpiritSwap launched in April 2021 and later peaked near $373.03 million of TVL.","value":"SpiritSwap launched in April 2021 and later peaked near $373.03 million of TVL.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spiritswap:treasury-context","source:spiritswap:tvl"],"evidence_locator":"Launch report and historical provider series.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spiritswap:section:what_happened:2","field_path":"analysis.sections.what_happened.body","assertion":"Multichain-linked treasury losses triggered the announced September 2023 closure plan.","value":"Multichain-linked treasury losses triggered the announced September 2023 closure plan.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spiritswap:shutdown","source:spiritswap:treasury-context"],"evidence_locator":"Contemporary reports.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spiritswap:section:what_happened:3","field_path":"analysis.sections.what_happened.body","assertion":"A community-approved transfer to Power and treasury commitment averted immediate closure.","value":"A community-approved transfer to Power and treasury commitment averted immediate closure.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spiritswap:rescue"],"evidence_locator":"Contemporary rescue report.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spiritswap:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body","assertion":"Treasury dependence on Multichain turned an external infrastructure failure into an operating crisis.","value":"Treasury dependence on Multichain turned an external infrastructure failure into an operating crisis.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:spiritswap:shutdown","source:spiritswap:treasury-context"],"evidence_locator":"Reported treasury loss and cost shortfall.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spiritswap:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body","assertion":"Transferable code, governance and community created a rescue option instead of unavoidable closure.","value":"Transferable code, governance and community created a rescue option instead of unavoidable closure.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:spiritswap:rescue","source:spiritswap:app"],"evidence_locator":"Handoff and continued surface.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spiritswap:section:why_this_outcome:3","field_path":"analysis.sections.why_this_outcome.body","assertion":"The public record does not decompose current weakness among Fantom decline, incentives, competition and post-rescue execution.","value":"The public record does not decompose current weakness among Fantom decline, incentives, competition and post-rescue execution.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:spiritswap:tvl","source:spiritswap:volume","source:spiritswap:rescue"],"evidence_locator":"Outcome series without causal allocation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spiritswap:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body","assertion":"SpiritSwap chose Fantom specialization and bridge-assisted distribution.","value":"SpiritSwap chose Fantom specialization and bridge-assisted distribution.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spiritswap:app","source:spiritswap:treasury-context"],"evidence_locator":"Product and bridge descriptions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spiritswap:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body","assertion":"The venue chose SPIRIT emissions and inSPIRIT locking for liquidity and governance.","value":"The venue chose SPIRIT emissions and inSPIRIT locking for liquidity and governance.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spiritswap:app","source:spiritswap:inspirit"],"evidence_locator":"Token-system surfaces.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spiritswap:section:strategic_choices:3","field_path":"analysis.sections.strategic_choices.body","assertion":"The community chose transfer and recapitalization instead of closure.","value":"The community chose transfer and recapitalization instead of closure.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spiritswap:rescue"],"evidence_locator":"Reported rescue vote and funding commitment.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spiritswap:section:operating_model:1","field_path":"analysis.sections.operating_model.body","assertion":"SpiritSwap combined swap fees with SPIRIT farming and inSPIRIT governance.","value":"SpiritSwap combined swap fees with SPIRIT farming and inSPIRIT governance.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spiritswap:app","source:spiritswap:inspirit","source:spiritswap:treasury-context"],"evidence_locator":"Product and historical economics.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spiritswap:section:operating_model:2","field_path":"analysis.sections.operating_model.body","assertion":"The adapter recorded about $95 of 30-day fees and $13.85 of revenue at review time.","value":"The adapter recorded about $95 of 30-day fees and $13.85 of revenue at review time.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spiritswap:fees","source:spiritswap:revenue"],"evidence_locator":"Current provider observations.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spiritswap:section:operating_model:3","field_path":"analysis.sections.operating_model.body","assertion":"Current TVL and fees do not prove operator solvency or reliable user execution.","value":"Current TVL and fees do not prove operator solvency or reliable user execution.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:spiritswap:tvl","source:spiritswap:swap"],"evidence_locator":"Metric and route limitations.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spiritswap:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body","assertion":"SPIRIT funded liquidity incentives and inSPIRIT locks carried governance and advertised fee rights.","value":"SPIRIT funded liquidity incentives and inSPIRIT locks carried governance and advertised fee rights.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spiritswap:app","source:spiritswap:inspirit"],"evidence_locator":"Current branded token description.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spiritswap:section:token_and_value_capture:2","field_path":"analysis.sections.token_and_value_capture.body","assertion":"Current tracked holder revenue was zero at review time.","value":"Current tracked holder revenue was zero at review time.","as_of":"2026-08-03","confidence":"medium","kind":"fact","source_ids":["source:spiritswap:revenue"],"evidence_locator":"Adapter observation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spiritswap:section:token_and_value_capture:3","field_path":"analysis.sections.token_and_value_capture.body","assertion":"Post-rescue net token distributions and liabilities remain unknown.","value":"Post-rescue net token distributions and liabilities remain unknown.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:spiritswap:rescue","source:spiritswap:revenue"],"evidence_locator":"No complete current distribution ledger.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spiritswap:section:counterfactual:1","field_path":"analysis.sections.counterfactual.body","assertion":"Diversified treasury custody and bridge-risk caps could reduce a single external failure’s impact on runway.","value":"Diversified treasury custody and bridge-risk caps could reduce a single external failure’s impact on runway.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:spiritswap:shutdown","source:spiritswap:treasury-context"],"evidence_locator":"Observed concentration supports the alternative.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spiritswap:section:counterfactual:2","field_path":"analysis.sections.counterfactual.body","assertion":"A public control and liability ledger could make the rescue easier to evaluate.","value":"A public control and liability ledger could make the rescue easier to evaluate.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:spiritswap:rescue","source:spiritswap:app"],"evidence_locator":"Handoff without complete current disclosure.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spiritswap:section:counterfactual:3","field_path":"analysis.sections.counterfactual.body","assertion":"No source proves multichain expansion or closure would have produced a better user outcome.","value":"No source proves multichain expansion or closure would have produced a better user outcome.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:spiritswap:shutdown","source:spiritswap:rescue"],"evidence_locator":"Alternatives were not observed.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spiritswap:section:risks_and_unknowns:1","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"The original audit did not cover later treasury, bridge and governance failures.","value":"The original audit did not cover later treasury, bridge and governance failures.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:spiritswap:audit","source:spiritswap:shutdown"],"evidence_locator":"Audit scope and later incident.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spiritswap:section:risks_and_unknowns:2","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"The public interface currently exposes broken zero or NaN headline fields.","value":"The public interface currently exposes broken zero or NaN headline fields.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spiritswap:app"],"evidence_locator":"Current rendered surface.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spiritswap:section:risks_and_unknowns:3","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"Current control, liabilities, recurring users and inSPIRIT distributions remain unknown.","value":"Current control, liabilities, recurring users and inSPIRIT distributions remain unknown.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:spiritswap:rescue","source:spiritswap:app","source:spiritswap:revenue"],"evidence_locator":"No complete current disclosure.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spiritswap:section:lifecycle:1","field_path":"analysis.sections.lifecycle.body","assertion":"SpiritSwap grew from April 2021 launch to a January 2022 TVL peak.","value":"SpiritSwap grew from April 2021 launch to a January 2022 TVL peak.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spiritswap:treasury-context","source:spiritswap:tvl"],"evidence_locator":"Launch and provider history.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:spiritswap:section:lifecycle:2","field_path":"analysis.sections.lifecycle.body","assertion":"The 2023 closure plan was reversed by a community-approved rescue.","value":"The 2023 closure plan was reversed by a community-approved rescue.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:spiritswap:shutdown","source:spiritswap:rescue"],"evidence_locator":"Dated reports.","support_direction":"supports","note":null,